/**
 * Self-contained Client-Side Search Engine (Fuse.js API compatible)
 * Scholar Q&A Website
 * Provides zero-dependency fuzzy multi-key search and relevance ranking.
 */

(function (window) {
  'use strict';

  function normalize(str) {
    return (str || '')
      .toString()
      .toLowerCase()
      .normalize('NFD')
      .replace(/[\u0300-\u036f]/g, '')
      .trim();
  }

  // Calculate Levenshtein edit distance between two strings
  function editDistance(a, b) {
    if (a.length === 0) return b.length;
    if (b.length === 0) return a.length;

    const matrix = [];
    for (let i = 0; i <= b.length; i++) matrix[i] = [i];
    for (let j = 0; j <= a.length; j++) matrix[0][j] = j;

    for (let i = 1; i <= b.length; i++) {
      for (let j = 1; j <= a.length; j++) {
        if (b.charAt(i - 1) === a.charAt(j - 1)) {
          matrix[i][j] = matrix[i - 1][j - 1];
        } else {
          matrix[i][j] = Math.min(
            matrix[i - 1][j - 1] + 1, // substitution
            matrix[i][j - 1] + 1,     // insertion
            matrix[i - 1][j] + 1      // deletion
          );
        }
      }
    }

    return matrix[b.length][a.length];
  }

  class Fuse {
    constructor(list, options = {}) {
      this.list = Array.isArray(list) ? list : [];
      this.options = {
        keys: options.keys || [],
        threshold: options.threshold !== undefined ? options.threshold : 0.4,
        minMatchCharLength: options.minMatchCharLength || 2,
        ignoreLocation: options.ignoreLocation !== undefined ? options.ignoreLocation : true,
        ...options
      };
    }

    search(pattern) {
      if (!pattern || typeof pattern !== 'string') return [];
      const cleanPattern = normalize(pattern);
      if (cleanPattern.length < (this.options.minMatchCharLength || 1)) return [];

      const queryTokens = cleanPattern.split(/\s+/).filter(Boolean);
      const results = [];

      for (let i = 0; i < this.list.length; i++) {
        const item = this.list[i];
        let bestItemScore = Infinity;
        let matched = false;

        for (let k = 0; k < this.options.keys.length; k++) {
          const keyDef = this.options.keys[k];
          const keyName = typeof keyDef === 'string' ? keyDef : keyDef.name;
          const keyWeight = (typeof keyDef === 'object' && keyDef.weight) ? keyDef.weight : 1;

          const textValue = normalize(item[keyName]);
          if (!textValue) continue;

          // Check direct substring match
          if (textValue.includes(cleanPattern)) {
            // Exact full phrase match
            const score = (cleanPattern.length / textValue.length) * 0.1 * (1 / keyWeight);
            if (score < bestItemScore) bestItemScore = score;
            matched = true;
            continue;
          }

          // Check token matches
          let tokenMatches = 0;
          let tokenScoresSum = 0;

          for (const token of queryTokens) {
            if (textValue.includes(token)) {
              tokenMatches++;
              tokenScoresSum += 0.2;
            } else {
              // Fuzzy word comparison
              const words = textValue.split(/[\s,.'";:?!()-]+/);
              let bestWordDist = Infinity;
              for (const word of words) {
                if (!word) continue;
                if (Math.abs(word.length - token.length) > 3) continue;
                const dist = editDistance(token, word);
                if (dist < bestWordDist) bestWordDist = dist;
              }

              const maxAllowedDist = token.length <= 4 ? 1 : 2;
              if (bestWordDist <= maxAllowedDist) {
                tokenMatches++;
                tokenScoresSum += 0.4 + (bestWordDist * 0.2);
              }
            }
          }

          if (tokenMatches === queryTokens.length) {
            matched = true;
            const avgScore = (tokenScoresSum / queryTokens.length) * (1 / keyWeight);
            if (avgScore < bestItemScore) bestItemScore = avgScore;
          }
        }

        if (matched && bestItemScore <= (this.options.threshold + 0.5)) {
          results.push({
            item,
            score: bestItemScore,
            refIndex: i
          });
        }
      }

      // Sort by best score ascending (lower score is better relevance)
      results.sort((a, b) => a.score - b.score);
      return results;
    }
  }

  window.Fuse = Fuse;
})(window);

